  {
   "id": "no_termination_for_convenience_clause",
   "severity": "low",
   "message": "The NDA has a fixed 18-month term but no clause allowing early termination without cause, so Northwind cannot exit early; the 5-year confidentiality tail runs from termination.",
   "quote": "This Agreement will remain in effect for eighteen (18) months from the Effective Date."
  },
  {
   "id": "florida_governing_law",
   "severity": "low",
   "message": "Governing law is Florida, not Northwind's home state of Delaware, which may add cost or unfamiliarity in a dispute.",
   "quote": "the laws of the State of Florida, without regard to its conflict of laws principles"
  },
  {
   "id": "no_remedies_or_injunctive_relief",
   "severity": "low",
   "message": "Dispute resolution is limited to executive discussions followed by unspecified remedies; there is no express injunctive relief clause for breaches of confidentiality.",
   "quote": "If the dispute is not resolved within twenty Business Days, either Party may pursue the remedies available to it."
  },
  {
   "id": "expired_term",
   "severity": "medium",
   "message": "The 18-month term from 2025-01-02 ended around 2026-07-02, before today's date. Any ongoing information sharing is no longer covered by the NDA, though the 5-year confidentiality obligations survive.",
   "quote": "This Agreement will remain in effect for eighteen (18) months from the Effective Date."
  }
